import json
data = json.load(open('/app/resources/treasury_bulletin_2007_12.json'))
# Print keys at each level
def explore(obj, indent=0):
    if isinstance(obj, dict):
        for k, v in obj.items():
            print(' ' * indent + str(k))
            if isinstance(v, (dict, list)):
                explore(v, indent+2)
    elif isinstance(obj, list) and len(obj) > 0:
        print(' ' * indent + f'list[{len(obj)}]')
        explore(obj[0], indent+2)

explore(data)
